    24	    public static void main(String[] args) {
    25	        String dbUrl = System.getenv("DB_URL");
    26	        if (dbUrl == null || dbUrl.isBlank()) {
    27	            throw new IllegalStateException("A variável de ambiente DB_URL é obrigatória.");
    28	        }
    29	        String portEnv = System.getenv("PORT");
    30	        int port = portEnv == null || portEnv.isBlank() ? 7070 : Integer.parseInt(portEnv.trim());
