     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.domain.ApiException;
     4	import br.com.marealta.domain.ErrorCode;
     5	import br.com.marealta.domain.RatePlan;
     6	import br.com.marealta.service.NewReservation;
     7	import br.com.marealta.service.ReportService;
     8	import br.com.marealta.service.ReservationService;
     9	import com.fasterxml.jackson.databind.JsonNode;
    10	import com.fasterxml.jackson.databind.ObjectMapper;
    11	import com.fasterxml.jackson.databind.SerializationFeature;
    12	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
    13	import io.javalin.Javalin;
    14	import io.javalin.http.Context;
    15	import io.javalin.json.JavalinJackson;
    16	
    17	import java.time.LocalDate;
    18	import java.time.YearMonth;
    19	import java.time.format.DateTimeParseException;
    20	import java.util.Map;
    21	
    22	public final class App {
    23	    private static final String CSV = "text/csv; charset=utf-8";
    24	
    25	    private final ReservationService reservations;
    26	    private final ReportService reports;
    27	    private final ObjectMapper mapper = new ObjectMapper()
    28	            .registerModule(new JavaTimeModule())
    29	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    30	
    31	    public App(ReservationService reservations, ReportService reports) {
    32	        this.reservations = reservations;
    33	        this.reports = reports;
    34	    }
    35	
    36	    public Javalin create() {
    37	        Javalin app = Javalin.create(config -> config.jsonMapper(new JavalinJackson(mapper, false)));
    38	
    39	        app.get("/rooms", ctx -> ctx.json(reservations.listRooms()));
    40	        app.post("/reservations", ctx -> ctx.status(201).json(reservations.create(parseNewReservation(ctx))));
    41	        app.get("/reservations/{id}", ctx -> ctx.json(reservations.get(id(ctx))));
    42	        app.post("/reservations/{id}/confirmation", ctx -> ctx.json(reservations.confirm(id(ctx))));
    43	        app.post("/reservations/{id}/cancellation", ctx -> ctx.json(reservations.cancel(id(ctx))));
    44	        app.post("/reservations/{id}/check-in", ctx -> ctx.json(reservations.checkIn(id(ctx))));
    45	        app.post("/reservations/{id}/check-out", ctx -> ctx.json(reservations.checkOut(id(ctx))));
    46	        app.get("/reservations/{id}/document", ctx -> ctx.json(reservations.document(id(ctx))));
    47	        app.get("/messages", ctx -> ctx.json(reservations.listMessages()));
    48	        app.get("/reports/occupancy", ctx -> ctx.contentType(CSV).result(reports.occupancy(dateParam(ctx, "date"))));
    49	        app.get("/reports/revenue", ctx -> ctx.contentType(CSV).result(reports.revenue(monthParam(ctx, "month"))));
    50	
    51	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.code(), e.getMessage()));
    52	        app.exception(Exception.class, (e, ctx) -> {
    53	            e.printStackTrace();
    54	            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", "Erro interno."));
    55	        });
    56	        return app;
    57	    }
    58	
    59	    private static void error(Context ctx, ErrorCode code, String message) {
    60	        ctx.status(code.httpStatus()).json(Map.of("error", code.name(), "message", message));
    61	    }
    62	
    63	    private static long id(Context ctx) {
    64	        try {
    65	            return Long.parseLong(ctx.pathParam("id"));
    66	        } catch (NumberFormatException e) {
    67	            throw new ApiException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva inexistente.");
    68	        }
    69	    }
    70	
    71	    private static LocalDate dateParam(Context ctx, String name) {
    72	        String value = ctx.queryParam(name);
    73	        try {
    74	            if (value != null) {
    75	                return LocalDate.parse(value);
    76	            }
    77	        } catch (DateTimeParseException ignored) {
    78	            // cai no erro abaixo
    79	        }
    80	        throw invalid("Parâmetro '" + name + "' ausente ou fora do formato AAAA-MM-DD.");
    81	    }
    82	
    83	    private static YearMonth monthParam(Context ctx, String name) {
    84	        String value = ctx.queryParam(name);
    85	        try {
    86	            if (value != null) {
    87	                return YearMonth.parse(value);
    88	            }
    89	        } catch (DateTimeParseException ignored) {
    90	            // cai no erro abaixo
    91	        }
    92	        throw invalid("Parâmetro '" + name + "' ausente ou fora do formato AAAA-MM.");
    93	    }
    94	
    95	    private NewReservation parseNewReservation(Context ctx) {
    96	        JsonNode body;
    97	        try {
    98	            body = mapper.readTree(ctx.body());
    99	        } catch (Exception e) {
   100	            throw invalid("O corpo da requisição não é um JSON válido.");
   101	        }
   102	        if (body == null || !body.isObject()) {
   103	            throw invalid("O corpo da requisição deve ser um objeto JSON.");
   104	        }
   105	        int roomNumber = integer(body, "roomNumber");
   106	        String name = text(body, "guestName");
   107	        String email = text(body, "guestEmail");
   108	        String cpf = text(body, "guestCpf");
   109	        LocalDate checkIn = date(body, "checkIn");
   110	        LocalDate checkOut = date(body, "checkOut");
   111	        int guests = integer(body, "guests");
   112	        RatePlan plan;
   113	        try {
   114	            plan = RatePlan.valueOf(text(body, "ratePlan"));
   115	        } catch (IllegalArgumentException e) {
   116	            throw invalid("Campo 'ratePlan' inválido.");
   117	        }
   118	        return new NewReservation(roomNumber, name, email, cpf, checkIn, checkOut, guests, plan);
   119	    }
   120	
   121	    private static String text(JsonNode body, String field) {
   122	        JsonNode node = body.get(field);
   123	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
   124	            throw invalid("Campo '" + field + "' ausente ou inválido.");
   125	        }
   126	        return node.asText().strip();
   127	    }
   128	
   129	    private static int integer(JsonNode body, String field) {
   130	        JsonNode node = body.get(field);
   131	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
   132	            throw invalid("Campo '" + field + "' ausente ou inválido.");
   133	        }
   134	        return node.asInt();
   135	    }
   136	
   137	    private static LocalDate date(JsonNode body, String field) {
   138	        String value = text(body, field);
   139	        try {
   140	            return LocalDate.parse(value);
   141	        } catch (DateTimeParseException e) {
   142	            throw invalid("Campo '" + field + "' fora do formato AAAA-MM-DD.");
   143	        }
   144	    }
   145	
   146	    private static ApiException invalid(String message) {
   147	        return new ApiException(ErrorCode.INVALID_REQUEST, message);
   148	    }
   149	}
