     1	package br.com.marealta.service;
     2	
     3	import br.com.marealta.domain.ApiException;
     4	import br.com.marealta.domain.ErrorCode;
     5	import br.com.marealta.domain.Message;
     6	import br.com.marealta.domain.PricingCalculator;
     7	import br.com.marealta.domain.Quote;
     8	import br.com.marealta.domain.Receipt;
     9	import br.com.marealta.domain.Reservation;
    10	import br.com.marealta.domain.ReservationStatus;
    11	import br.com.marealta.domain.Money;
    12	import br.com.marealta.domain.Room;
    13	import br.com.marealta.events.ReservationEvent;
    14	import br.com.marealta.events.ReservationEvents;
    15	
    16	import java.util.List;
    17	
    18	public class ReservationService {
    19	    private final Transactions tx;
    20	    private final RoomRepository rooms;
    21	    private final ReservationRepository reservations;
    22	    private final MessageStore messages;
    23	    private final ReservationEvents events;
    24	
    25	    public ReservationService(Transactions tx, RoomRepository rooms, ReservationRepository reservations,
    26	                              MessageStore messages, ReservationEvents events) {
    27	        this.tx = tx;
    28	        this.rooms = rooms;
    29	        this.reservations = reservations;
    30	        this.messages = messages;
    31	        this.events = events;
    32	    }
    33	
    34	    public List<Room> listRooms() {
    35	        return tx.run(rooms::findAll);
    36	    }
    37	
    38	    public List<Message> listMessages() {
    39	        return tx.run(messages::findAll);
    40	    }
    41	
    42	    public Reservation create(NewReservation cmd) {
    43	        if (!cmd.checkOut().isAfter(cmd.checkIn())) {
    44	            throw new ApiException(ErrorCode.INVALID_REQUEST, "A saída deve ser depois da entrada.");
    45	        }
    46	        if (cmd.guests() < 1) {
    47	            throw new ApiException(ErrorCode.INVALID_REQUEST, "É preciso pelo menos um hóspede.");
    48	        }
    49	        return tx.run(() -> {
    50	            Room room = rooms.findForUpdate(cmd.roomNumber())
    51	                    .orElseThrow(() -> new ApiException(ErrorCode.ROOM_NOT_FOUND, "Quarto inexistente."));
    52	            if (cmd.guests() > room.capacity()) {
    53	                throw new ApiException(ErrorCode.CAPACITY_EXCEEDED,
    54	                        "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes.");
    55	            }
    56	            if (reservations.existsOverlapping(room.number(), cmd.checkIn(), cmd.checkOut())) {
    57	                throw new ApiException(ErrorCode.ROOM_UNAVAILABLE, "Quarto já reservado em alguma das noites.");
    58	            }
    59	            Quote quote = PricingCalculator.quote(room, cmd.checkIn(), cmd.checkOut(), cmd.ratePlan());
    60	            Reservation draft = new Reservation(0, room.number(), cmd.guestName(), cmd.guestEmail(),
    61	                    cmd.guestCpf(), cmd.checkIn(), cmd.checkOut(), cmd.guests(), cmd.ratePlan(), quote.nights(),
    62	                    quote.subtotal(), quote.discount(), quote.total(), ReservationStatus.PENDING, Money.ZERO, null);
    63	            return reservations.insert(draft);
    64	        });
    65	    }
    66	
    67	    public Reservation get(long id) {
    68	        return tx.run(() -> reservations.find(id).orElseThrow(ReservationService::notFound));
    69	    }
    70	
    71	    public Reservation confirm(long id) {
    72	        return tx.run(() -> {
    73	            Reservation current = lock(id);
    74	            Reservation updated = current.confirm();
    75	            reservations.update(updated);
    76	            events.publish(new ReservationEvent.Confirmed(updated, roomOf(updated)));
    77	            return updated;
    78	        });
    79	    }
    80	
    81	    public Reservation cancel(long id) {
    82	        return tx.run(() -> {
    83	            Reservation current = lock(id);
    84	            Reservation updated = current.cancel();
    85	            reservations.update(updated);
    86	            events.publish(new ReservationEvent.Cancelled(updated, roomOf(updated), current.status()));
    87	            return updated;
    88	        });
    89	    }
    90	
    91	    public Reservation checkIn(long id) {
    92	        return tx.run(() -> {
    93	            Reservation updated = lock(id).checkInGuest();
    94	            reservations.update(updated);
    95	            return updated;
    96	        });
    97	    }
    98	
    99	    public Receipt checkOut(long id) {
   100	        return tx.run(() -> {
   101	            Reservation updated = lock(id).checkOutGuest();
   102	            reservations.update(updated);
   103	            return Receipt.of(updated, roomOf(updated));
   104	        });
   105	    }
   106	
   107	    /** Segunda via do comprovante: só existe para reserva paga. */
   108	    public Receipt document(long id) {
   109	        return tx.run(() -> {
