    25	
    26	    public String occupancy(LocalDate night) {
    27	        return tx.run(() -> {
    28	            Map<Integer, Room> byNumber = rooms.findAll().stream()
    29	                    .collect(Collectors.toMap(Room::number, Function.identity()));
    30	            List<Reservation> occupying = reservations.findPaidOccupying(night);
    31	            StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    32	            for (Reservation r : occupying) {
    33	                csv.append(r.roomNumber()).append(',')
    34	                        .append(byNumber.get(r.roomNumber()).type()).append(',')
    35	                        .append(r.id()).append(',')
    36	                        .append(r.checkIn()).append(',')
    37	                        .append(r.checkOut()).append('\n');
    38	            }
    39	            long occupied = occupying.stream().map(Reservation::roomNumber).distinct().count();
    40	            csv.append("total,").append(occupied).append('/').append(byNumber.size()).append('\n');
    41	            return csv.toString();
    42	        });
    43	    }
    44	
    45	    public String revenue(YearMonth month) {
    46	        return tx.run(() -> {
    47	            List<Reservation> starting = reservations.findCheckingInBetween(
    48	                    month.atDay(1), month.plusMonths(1).atDay(1));
    49	            StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    50	            BigDecimal total = Money.ZERO;
    51	            for (Reservation r : starting) {
    52	                BigDecimal amount = r.netAmount();
    53	                if (amount.signum() <= 0) {
    54	                    continue;
    55	                }
    56	                csv.append(r.id()).append(',')
    57	                        .append(r.roomNumber()).append(',')
    58	                        .append(r.checkIn()).append(',')
    59	                        .append(r.checkOut()).append(',')
    60	                        .append(r.status()).append(',')
    61	                        .append(amount.toPlainString()).append('\n');
    62	                total = total.add(amount);
    63	            }
    64	            csv.append("total,").append(Money.round(total).toPlainString()).append('\n');
    65	            return csv.toString();
    66	        });
    67	    }
    68	}
