     1	package br.com.marealta.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	
     6	public final class PricingCalculator {
     7	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     8	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
     9	
    10	    private PricingCalculator() {
    11	    }
    12	
    13	    /** Alta temporada: 15/12 até o fim de fevereiro, e julho inteiro. */
    14	    public static boolean isHighSeason(LocalDate night) {
    15	        int month = night.getMonthValue();
    16	        return month == 1 || month == 2 || month == 7
    17	                || (month == 12 && night.getDayOfMonth() >= 15);
    18	    }
    19	
    20	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    21	        BigDecimal rate = Money.round(room.nightlyRate());
    22	        return isHighSeason(night) ? Money.round(rate.multiply(HIGH_SEASON_FACTOR)) : rate;
    23	    }
    24	
    25	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    26	        BigDecimal subtotal = Money.ZERO;
    27	        int nights = 0;
    28	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    29	            subtotal = Money.round(subtotal.add(nightPrice(room, night)));
    30	            nights++;
    31	        }
    32	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
    33	                ? Money.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT))
    34	                : Money.ZERO;
    35	        BigDecimal total = Money.round(subtotal.subtract(discount));
    36	        return new Quote(nights, subtotal, discount, total);
    37	    }
    38	}
