    20	        BigDecimal total) {
    21	
    22	    public static final String TITLE = "Comprovante de reserva";
    23	    private static final DateTimeFormatter BR_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    24	
    25	    public static Receipt of(Reservation r, Room room) {
    26	        return new Receipt(TITLE, r.id(), r.guestName(), r.guestCpf(), room.number(), room.type(),
    27	                r.checkIn(), r.checkOut(), r.nights(), r.subtotal(), r.discount(), r.total());
    28	    }
    29	
    30	    public static String formatDate(LocalDate date) {
    31	        return BR_DATE.format(date);
    32	    }
    33	
    34	    /** Texto do comprovante, sem quebra de linha no final. */
    35	    public String toText() {
    36	        StringBuilder sb = new StringBuilder();
    37	        sb.append(title).append(" nº ").append(reservationId).append('\n');
    38	        sb.append("Hóspede: ").append(guestName).append(" (CPF ").append(formatCpf(guestCpf)).append(")\n");
    39	        sb.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    40	        sb.append("Entrada: ").append(formatDate(checkIn)).append(" | Saída: ").append(formatDate(checkOut))
    41	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
    42	        sb.append("Diárias: ").append(Money.format(subtotal)).append('\n');
    43	        if (discount.signum() > 0) {
    44	            sb.append("Desconto: ").append(Money.format(discount)).append('\n');
    45	        }
    46	        sb.append("Total: ").append(Money.format(total));
    47	        return sb.toString();
    48	    }
    49	
    50	    private static String formatCpf(String cpf) {
    51	        if (cpf.matches("\\d{11}")) {
    52	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
    53	        }
    54	        return cpf;
    55	    }
