     1	package br.com.marealta.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	
     6	public record Reservation(
     7	        long id,
     8	        int roomNumber,
     9	        String guestName,
    10	        String guestEmail,
    11	        String guestCpf,
    12	        LocalDate checkIn,
    13	        LocalDate checkOut,
    14	        int guests,
    15	        RatePlan ratePlan,
    16	        int nights,
    17	        BigDecimal subtotal,
    18	        BigDecimal discount,
    19	        BigDecimal total,
    20	        ReservationStatus status,
    21	        BigDecimal amountPaid,
    22	        BigDecimal refund) {
    23	
    24	    public Reservation confirm() {
    25	        require(status == ReservationStatus.PENDING, "Só é possível confirmar uma reserva pendente.");
    26	        return with(ReservationStatus.CONFIRMED, total, refund);
    27	    }
    28	
    29	    public Reservation checkInGuest() {
    30	        require(status == ReservationStatus.CONFIRMED, "Só é possível fazer check-in de uma reserva confirmada.");
    31	        return with(ReservationStatus.CHECKED_IN, amountPaid, refund);
    32	    }
    33	
    34	    public Reservation checkOutGuest() {
    35	        require(status == ReservationStatus.CHECKED_IN, "Só é possível fazer check-out de uma reserva com check-in.");
    36	        return with(ReservationStatus.CHECKED_OUT, amountPaid, refund);
    37	    }
    38	
    39	    /** Cancela e calcula o reembolso: só o plano normal, e só do que foi pago. */
    40	    public Reservation cancel() {
    41	        require(status == ReservationStatus.PENDING || status == ReservationStatus.CONFIRMED,
    42	                "Só é possível cancelar uma reserva pendente ou confirmada.");
    43	        BigDecimal refunded = ratePlan == RatePlan.STANDARD ? amountPaid : Money.ZERO;
    44	        return with(ReservationStatus.CANCELLED, amountPaid, refunded);
    45	    }
    46	
    47	    public Reservation withId(long newId) {
    48	        return new Reservation(newId, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests,
    49	                ratePlan, nights, subtotal, discount, total, status, amountPaid, refund);
    50	    }
    51	
    52	    /** Dinheiro que ficou com a pousada: pago menos devolvido. */
    53	    public BigDecimal netAmount() {
    54	        return Money.round(amountPaid.subtract(refund == null ? Money.ZERO : refund));
    55	    }
    56	
    57	    private Reservation with(ReservationStatus newStatus, BigDecimal paid, BigDecimal newRefund) {
    58	        return new Reservation(id, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests,
    59	                ratePlan, nights, subtotal, discount, total, newStatus, paid, newRefund);
    60	    }
    61	
    62	    private static void require(boolean condition, String message) {
    63	        if (!condition) {
    64	            throw new ApiException(ErrorCode.OPERATION_NOT_ALLOWED, message);
    65	        }
    66	    }
    67	}
