 18	
 19	class HttpApiTest {
 20	    private static Javalin server;
 21	    private static String base;
 22	    private static final HttpClient http = HttpClient.newHttpClient();
 23	    private static final ObjectMapper json = new ObjectMapper();
 24	
 25	    @BeforeAll
 26	    static void start() {
 27	        InMemory m = new InMemory();
 28	        server = new App(m.service, m.reports).create().start(0);
 29	        base = "http://localhost:" + server.port();
 30	    }
 31	
 32	    @AfterAll
 33	    static void stop() {
 34	        server.stop();
 35	    }
 36	
 37	    private HttpResponse<String> send(String method, String path, String body) throws Exception {
 38	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(base + path));
 39	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
 40	        return http.send(b.build(), HttpResponse.BodyHandlers.ofString());
 41	    }
 42	
 43	    private static final String VALID = """
 44	            {"roomNumber":201,"guestName":"Carla Dias","guestEmail":"c@x.com","guestCpf":"11122233344",
 45	             "checkIn":"2027-03-10","checkOut":"2027-03-12","guests":2,"ratePlan":"STANDARD"}""";
 46	
 47	    @Test
 48	    void fullFlow() throws Exception {
 49	        JsonNode rooms = json.readTree(send("GET", "/rooms", null).body());
 50	        assertEquals(5, rooms.size());
 51	        assertEquals(389.90, rooms.get(2).get("nightlyRate").asDouble());
 52	
 53	        HttpResponse<String> created = send("POST", "/reservations", VALID);
 54	        assertEquals(201, created.statusCode());
 55	        JsonNode r = json.readTree(created.body());
 56	        long id = r.get("id").asLong();
 57	        assertEquals("PENDING", r.get("status").asText());
 58	        assertEquals("2027-03-10", r.get("checkIn").asText());
 59	        assertTrue(r.get("refund").isNull());
 60	        assertTrue(created.body().contains("\"amountPaid\":0.00"), created.body());
 61	        assertTrue(created.body().contains("\"total\":779.80"), created.body());
 62	
 63	        assertEquals(409, send("POST", "/reservations", VALID).statusCode());
 64	        assertEquals(409, send("GET", "/reservations/" + id + "/document", null).statusCode());
 65	        assertEquals("CONFIRMED", json.readTree(send("POST", "/reservations/" + id + "/confirmation", null).body()).get("status").asText());
 66	        assertEquals("CHECKED_IN", json.readTree(send("POST", "/reservations/" + id + "/check-in", null).body()).get("status").asText());
 67	
 68	        HttpResponse<String> out = send("POST", "/reservations/" + id + "/check-out", null);
 69	        assertEquals(200, out.statusCode());
 70	        JsonNode doc = json.readTree(out.body());
 71	        assertEquals("Comprovante de reserva", doc.get("title").asText());
 72	        assertEquals("DELUXE", doc.get("roomType").asText());
 73	        assertEquals(json.readTree(send("GET", "/reservations/" + id + "/document", null).body()), doc);
 74	
 75	        JsonNode msgs = json.readTree(send("GET", "/messages", null).body());
 76	        assertEquals(3, msgs.size());
 77	        assertEquals("EMAIL", msgs.get(0).get("channel").asText());
 78	
 79	        HttpResponse<String> csv = send("GET", "/reports/revenue?month=2027-03", null);
 80	        assertTrue(csv.headers().firstValue("content-type").orElse("").toLowerCase().contains("text/csv"));
 81	        assertTrue(csv.headers().firstValue("content-type").orElse("").toLowerCase().contains("utf-8"));
 82	        assertTrue(csv.body().endsWith("total,779.80\n"));
 83	        assertTrue(send("GET", "/reports/occupancy?date=2027-03-10", null).body().endsWith("total,1/5\n"));
 84	    }
 85	
 86	    @Test
 87	    void errors() throws Exception {
 88	        assertEquals(400, send("POST", "/reservations", "não é json").statusCode());
 89	        assertEquals(400, send("POST", "/reservations", "{}").statusCode());
 90	        assertEquals(400, send("POST", "/reservations", VALID.replace("\"guests\":2", "\"guests\":\"2\"")).statusCode());
 91	        assertEquals(400, send("POST", "/reservations", VALID.replace("2027-03-12", "12/03/2027")).statusCode());
 92	        assertEquals(400, send("POST", "/reservations", VALID.replace("2027-03-12", "2027-03-10")).statusCode());
 93	        assertEquals(400, send("POST", "/reservations", VALID.replace("\"guests\":2", "\"guests\":0")).statusCode());
 94	        assertEquals(400, send("POST", "/reservations", VALID.replace("STANDARD\"", "OUTRO\"")).statusCode());
 95	
 96	        HttpResponse<String> noRoom = send("POST", "/reservations", VALID.replace("201", "999"));
 97	        assertEquals(404, noRoom.statusCode());
 98	        assertEquals("ROOM_NOT_FOUND", json.readTree(noRoom.body()).get("error").asText());
 99	        assertEquals(422, send("POST", "/reservations", VALID.replace("\"guests\":2", "\"guests\":9")).statusCode());
100	        assertEquals(404, send("GET", "/reservations/abc", null).statusCode());
101	        assertEquals(404, send("POST", "/reservations/12345/confirmation", null).statusCode());
102	        assertEquals(400, send("GET", "/reports/occupancy?date=10-07-2027", null).statusCode());
103	        assertEquals(400, send("GET", "/reports/revenue", null).statusCode());
104	        assertEquals(400, send("GET", "/reports/revenue?month=2027-13", null).statusCode());
105	    }
106	}
