410	        Reservation r = m.service.create(req(101, "2027-03-10", "2027-03-12", 1, RatePlan.STANDARD));
411	        assertNull(r.refund());
412	        assertEquals(ErrorCode.OPERATION_NOT_ALLOWED, codeOf(() -> m.service.checkIn(r.id())));
413	        assertEquals(ErrorCode.OPERATION_NOT_ALLOWED, codeOf(() -> m.service.checkOut(r.id())));
414	        assertEquals(ErrorCode.OPERATION_NOT_ALLOWED, codeOf(() -> m.service.document(r.id())));
415	        m.service.confirm(r.id());
416	        assertEquals(ErrorCode.OPERATION_NOT_ALLOWED, codeOf(() -> m.service.confirm(r.id())));
417	        assertEquals(ErrorCode.OPERATION_NOT_ALLOWED, codeOf(() -> m.service.checkOut(r.id())));
418	        m.service.document(r.id());
419	        m.service.checkIn(r.id());
420	        assertEquals(ErrorCode.OPERATION_NOT_ALLOWED, codeOf(() -> m.service.cancel(r.id())));
421	        Receipt out = m.service.checkOut(r.id());
422	        assertEquals("Comprovante de reserva", out.title());
423	        m.service.document(r.id());
424	        assertEquals(ErrorCode.RESERVATION_NOT_FOUND, codeOf(() -> m.service.get(99)));
